// flat #WCCChallenge 12.08.2023

var flats = [];
var fx = 75;
var fy = 55;

function setup() {
	createCanvas(525, 900);
  pixelDensity(1);
  // noLoop() removed for animation

  for (let y = 0; y < height; y += fy) {
    for (let x = 0; x < width; x += fx) {
      flats.push(new Flat(x, y, fx, fy));
    }
  }
}

function mouseClicked() {
  if (mouseButton === LEFT) {
    draw();
  }
}

function draw() {
  background(0, 0, 8);

  stroke(255,128);

  for (let f of flats) {
    f.update();
    f.show();
  }
}


class Flat {
  constructor(x, y, w, h) {
    this.x = x;
    this.y = y;
    this.w = w;
    this.h = h;

var clr = createVector(255, random(128, 255), 64).mult(random(0.35, 1));
    this.clr = random() < 0.25 ? color(192) : color(clr.x, clr.y, clr.z);
  }

  update() {

  }

  show() {
var x = this.x;
var y = this.y;
var w = this.w;
var h = this.h;
var w2 = w * 0.5;
var h2 = h * 0.5;

    push();
    translate(x, y);

    // outer rects
    fill(255, 128);
    noStroke();
    rect(0, 0, w, h);
    rect(w*0.5, 0, w*0.5, h*0.4);
    rect(w*0.5, 0, w*0.5, h*0.4);
    rect(0, h*0.4, w*0.5, h*0.6);


    // inner frame
    stroke(64, 8, 48);
    strokeWeight(h * 0.025)
    fill(160, 32, 64, 232);
    beginShape();
    for (let a = 0; a < TWO_PI; a += 0.1) {
      var x = sin(sin(sin(sin(sin(a))))) * w * 0.725 + w2;
      var y = cos(a) * h * 0.45 + h2;
      vertex(x, y);
    }
    endShape(CLOSE);

    // linien
    stroke(0, 128);
    strokeWeight(h * 0.025)
    line(0, h*0.4, w, h*0.4)
    line(w*0.5, 0, w*0.5, h)
    line(0, 0, w, 0);
    line(w, 0, w, h);
    line(0, h, w, h);
    line(0, 0, 0, h);


    // window
    var clr = this.clr;
    //colorMode(HSB, 100)
    // console.log(clr, hue(window.color(clr)), saturation(window.color(clr)), brightness(window.color(clr)))
    //fill(hue(window.color(clr)), saturation(window.color(clr)), brightness(window.color(clr)));
    fill("beige")

    rectMode(CENTER);
    rect(w2, h*0.4, w2, h2, min(w, h) * 0.05);

    // gardine
    stroke(212, 196)
    // left
    if (random()<0.65) {
var xe = random(w*0.25, w*0.75);
      for (let x = w*0.25; x < xe; x++) {
        strokeWeight(random(0.75,1.5));
        line(x, h*0.1725, x+random(-1,1), h*0.625);
      }
    }
    // right
    if (random()<0.65) {
var xs = random(w*0.25, w*0.75);
      for (let x = xs; x < w*0.75; x++) {
        strokeWeight(random(0.75,1.5));
        line(x, h*0.1725, x+random(-1,1), h*0.625);
      }
    }
    // frame
    noFill();
    stroke(64, 8, 32);
    strokeWeight(h * 0.025)
    rect(w2, h*0.4, w2, h2, min(w, h) * 0.05);

    pop(); 
  }
}




